void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalizing uv to work on all resolutions
    vec2 uv = fragCoord / iResolution.xy;

    // We want the position (0, 0) to represent center pixel
    // (currently is (0.5, 0.5))
    uv -= 0.5;

    // Now we need to fix the corners so that they span from
    // -1 to 1 (center will remain at 0)
    uv *= 2.0;

    // Multiplying our uv.x by the aspect ratio (width/height)
    // to avoid stretching and distortion
    uv.x *= iResolution.x / iResolution.y;

    // Distance from center of displ
    float dist = length(uv);

    // maximum amount of circles visible on screen
    // (usually shows one less than this amount)
    float circleCount = 5.0;

    // 1.0  : inwards
    // -1.0 : outwards
    float direction = -1.0;

    dist = sin(dist * circleCount + direction * iTime);

    // modified inverse function gives neon look
    // (increasing this value increases the brightness)
    dist = 0.015 / dist;

    fragColor = vec4(dist, dist, dist, 1.0);
}
